import glob,yaml,collections
rows={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    d=yaml.safe_load(open(f))
    rows[d['id']]=d
kids=collections.defaultdict(list)
for i in rows:
    if '.' in i:
        p=i.rsplit('.',1)[0]
        if p in rows: kids[p].append(i)
live={'pic-a','pic-b','pic-c','pic-d','pic-e','pic-f','pic-g','pic-h'}
for i in sorted(rows):
    d=rows[i]
    if d.get('status')!='active': continue
    o=(d.get('metadata') or {}).get('owner')
    ks=kids.get(i,[])
    st=collections.Counter(rows[k].get('status') for k in ks)
    print(f\"{i}\")
    print(f\"    owner={o or '-'} children={len(ks)} {dict(st) if ks else ''}\")
"

